#!/bin/sh
# Generated by Claude Code 2.1.330 (claude-opus-5-5)
set -eu

# Build Neverball's native dependencies for Quest (arm64-v8a, API 29).
# Run from the repository root.
#
#   ANDROID_NDK_HOME  Android NDK r27c
#   ANDROID_HOME      Android SDK with CMake 3.22.1
#   WORK              where to put sources, builds and the install prefix

NDK=${ANDROID_NDK_HOME:?set ANDROID_NDK_HOME}
SDK=${ANDROID_HOME:?set ANDROID_HOME}
WORK=${WORK:-$HOME/.cache/neverball-quest}
CMAKE=$SDK/cmake/3.22.1/bin/cmake
NINJA=$SDK/cmake/3.22.1/bin/ninja
SRC=$WORK/src
A=$WORK/prefix/android

android() { # name srcdir [cmake args...]
    name=$1; src=$2; shift 2
    $CMAKE -S "$src" -B "$WORK/build/$name-android" -G Ninja -DCMAKE_MAKE_PROGRAM=$NINJA \
        -DCMAKE_TOOLCHAIN_FILE=$NDK/build/cmake/android.toolchain.cmake \
        -DANDROID_ABI=arm64-v8a -DANDROID_PLATFORM=android-29 -DANDROID_STL=c++_static \
        -DCMAKE_BUILD_TYPE=Release -DCMAKE_INSTALL_PREFIX=$A -DCMAKE_PREFIX_PATH=$A \
        -DCMAKE_FIND_ROOT_PATH=$A "$@" >"$WORK/build/$name-android.log" 2>&1
    $CMAKE --build "$WORK/build/$name-android" --target install >>"$WORK/build/$name-android.log" 2>&1
    echo "ok android $name"
}

clone() { # dir url [branch]
    [ -d "$SRC/$1" ] || git clone -q --depth 1 ${3:+-b $3} "$2" "$SRC/$1"
}

mkdir -p $SRC $WORK/build

clone libpng        https://github.com/pnggroup/libpng.git libpng16
clone libjpeg-turbo https://github.com/libjpeg-turbo/libjpeg-turbo.git
clone ogg           https://github.com/xiph/ogg.git
clone vorbis        https://github.com/xiph/vorbis.git
clone SDL           https://github.com/libsdl-org/SDL.git SDL2
clone OpenXR-SDK    https://github.com/KhronosGroup/OpenXR-SDK.git

[ -d $SRC/SDL_ttf ] || git clone -q --depth 1 -b SDL2 --recurse-submodules \
    --shallow-submodules https://github.com/libsdl-org/SDL_ttf.git $SRC/SDL_ttf

# gl4es at the commit the web build uses.
if [ ! -d $SRC/gl4es ]; then
    git clone -q https://github.com/ptitSeb/gl4es.git $SRC/gl4es
    git -C $SRC/gl4es checkout -q "$(sed -n 's/^ENV GL4ES_COMMIT=//p' emscripten/Dockerfile)"
fi

# Dependencies
android libpng  $SRC/libpng -DPNG_SHARED=OFF -DPNG_TESTS=OFF -DPNG_TOOLS=OFF
android jpeg    $SRC/libjpeg-turbo -DENABLE_SHARED=OFF -DWITH_TURBOJPEG=OFF
android ogg     $SRC/ogg -DBUILD_SHARED_LIBS=OFF -DINSTALL_DOCS=OFF -DBUILD_TESTING=OFF
android vorbis  $SRC/vorbis -DBUILD_SHARED_LIBS=OFF -DBUILD_TESTING=OFF
android SDL2    $SRC/SDL -DSDL_SHARED=ON -DSDL_STATIC=OFF -DSDL_TEST=OFF
android SDL2_ttf $SRC/SDL_ttf -DBUILD_SHARED_LIBS=OFF -DSDL2TTF_VENDORED=ON -DSDL2TTF_HARFBUZZ=OFF -DSDL2TTF_SAMPLES=OFF
# gl4es has no install target.
$CMAKE -S $SRC/gl4es -B $WORK/build/gl4es-android -G Ninja -DCMAKE_MAKE_PROGRAM=$NINJA \
    -DCMAKE_TOOLCHAIN_FILE=$NDK/build/cmake/android.toolchain.cmake -DANDROID_ABI=arm64-v8a \
    -DANDROID_PLATFORM=android-29 -DCMAKE_BUILD_TYPE=Release \
    -DANDROID=ON -DSTATICLIB=ON -DUSE_ANDROID_LOG=ON >$WORK/build/gl4es-android.log 2>&1
$CMAKE --build $WORK/build/gl4es-android >>$WORK/build/gl4es-android.log 2>&1
mkdir -p $A/lib $A/include/gl4es
cp $SRC/gl4es/lib/libGL.a $A/lib/libgl4es.a
cp -r $SRC/gl4es/include/. $A/include/gl4es/
echo "ok android gl4es"
android openxr  $SRC/OpenXR-SDK -DBUILD_TESTS=OFF -DBUILD_API_LAYERS=OFF -DDYNAMIC_LOADER=ON
